#include <iostream>
#include <string>

class MyString {
public:
    std::string data;  // std::string supports move semantics
    // No user-defined constructors, so move constructor is synthesized
};

int main() {
    MyString s1;
    s1.data = "Hello, World!";  // Assign a value
    MyString s2 = std::move(s1);  // Synthesized move constructor transfers ownership
    std::cout << s2.data << std::endl;  // Outputs: Hello, World!
    // s1 is now in a valid but indeterminate state; avoid using it without reassignment
    return 0;
}
